  'diag.sanity.check.gravity_direction': 'direction des charges gravitaires',
  'diag.sanity.check.self_weight': 'poids propre',
  'diag.sanity.check.gravity_weight': 'poids par surface de plancher',
  'diag.sanity.check.period': 'période par rapport à la formule de la norme',
  'diag.sanity.check.tributary': 'charges des poteaux par aire d\'influence',
  'diag.sanity.check.materials': 'matériaux',
  'diag.sanity.check.sections': 'sections',
  'diag.sanity.check.geometry': 'échelle de la géométrie',
  'diag.sanity.check.load_path': 'cheminement des charges vers les appuis',
  'diag.sanity.check.connectivity': 'nœuds sur des barres auxquelles ils ne sont pas connectés',
  'diag.sanity.check.supports': 'disposition des appuis',
